import csv
from statistics import mean


def average_close(text):
    closes = [float(row["close"]) for row in csv.DictReader(text.splitlines())]
    return round(mean(closes), 2)

def price_of(prices, ticker):
    try:
        return prices[ticker]
    except KeyError:
        return None

