class Position:
    def __init__(self, ticker, qty, avg_price):
        self.ticker = ticker
        self.qty = qty
        self.avg_price = avg_price

    def buy(self, qty, price):
        cost = self.qty * self.avg_price + qty * price
        self.qty = self.qty + qty
        self.avg_price = cost / self.qty
